  /// 交通运输部 VTS 水域常用通信用语
  static const List<MaritimePhrase> vtsPhrases = [
    MaritimePhrase(id: '1.1', category: 'movement', en: 'Movement reports(Arrival, anchoring, berthing and departure reports)', zh: '动态报告(抵达、锚泊、靠泊和离港报告)'),
    MaritimePhrase(id: '1.1.1', category: 'movement', en: '...VTS ，this is M/V (name). I am passing through the reporting line(point)...(name),I am approaching to ...(name) Anchorage, Please advise me on traffic condition. over', zh: '...VTS，我是...船，我正通过...报告线(点)驶往...锚地，请告诉我附近船舶的情况'),
