    MaritimePhrase(id: '1.3.2', category: 'movement', en: 'The name of my vessel is ... , call sign ... .', zh: '我的船名是.../呼号是...'),
    MaritimePhrase(id: '1.3.4', category: 'movement', en: 'What is your position? . My position is ... .', zh: '你的位置在哪里？我的位置是...'),
    MaritimePhrase(id: '1.3.5', category: 'movement', en: 'What is your present course and speed? My present course is ... degrees, my speed is ... knots.', zh: '你现在的航向和速度是多少？我现在的航向是...度，速度是...节'),
    MaritimePhrase(id: '1.3.6', category: 'movement', en: 'From what direction are you approaching? I am approaching from ... .', zh: '你正从什么方向接近？我正从...接近'),
    MaritimePhrase(id: '1.3.7', category: 'movement', en: 'What is your destination? My port of destination / destination is ... .', zh: '你的目的港是哪里？我的目的港是...'),
    MaritimePhrase(id: '1.3.8', category: 'movement', en: 'What was your last port of call? My last port of call was ...', zh: '你的上一港是哪里？我的上一港是...'),
    MaritimePhrase(id: '1.3.9', category: 'movement', en: 'What is your flag state? My flag state is ... ..', zh: '你的船旗国是哪个国家？我的船旗国是...'),
    MaritimePhrase(id: '1.3.10', category: 'movement', en: 'What is your ETA in position ... ? My ETA is ... local.', zh: '你预计到达...处的时间是几点？我预计到达的时间是当地时间...点'),
    MaritimePhrase(id: '1.3.11', category: 'movement', en: 'What is your draft forward / aft? My draft forward / aft is ... metres.', zh: '你的前/后吃水是多少？我的前/后吃水是...米'),
    MaritimePhrase(id: '1.3.12', category: 'movement', en: 'What is your present maximum draft ? My present maximum draft is ... metres.', zh: '你现在的最大吃水是多少？我现在的最大吃水是...米'),
    MaritimePhrase(id: '1.3.13', category: 'movement', en: 'What is your freeboard? My freeboard is ... metres.', zh: '你的干舷是多少？我的干舷是...米'),
    MaritimePhrase(id: '1.3.14', category: 'movement', en: 'What is your air draft? My air draft is ... metres.', zh: '你船水线以上的最大高度有多少？我船水上以上的最大高度有...米'),
    MaritimePhrase(id: '1.3.15', category: 'movement', en: 'Are you underway? Yes, I am underway. No, I am not underway.', zh: '你船在航吗？是的，我船在航。不，我船不在航'),
    MaritimePhrase(id: '1.3.16', category: 'movement', en: 'I am ready to get underway.', zh: '我已做好在航准备'),
    MaritimePhrase(id: '1.3.17', category: 'movement', en: 'What is your full speed / full manoeuvring speed? My full speed / full manoeuvring speed is ... knots.', zh: '你的全速/最大操纵速度是多少？我的全速/最大操纵速度是...节'),
    MaritimePhrase(id: '1.3.18', category: 'movement', en: 'What is your cargo? My cargo is ... .', zh: '你船装的什么货？我船装的货是...'),
    MaritimePhrase(id: '1.3.19', category: 'movement', en: 'Do you carry any dangerous goods? Yes, I carry the following dangerous goods: ... kilogrammes / tonnes IMO Class ... . No, I do not carry any dangerous goods.', zh: '你船是否装有危险货物？是的，我船装有...（名称）危险货物...公斤/吨，此种货物属于IMO...类危险货物。不，我船没有危险货物'),
    MaritimePhrase(id: '1.3.20', category: 'movement', en: 'Do you have any deficiencies / restrictions? No, I have no deficiencies / restrictions. Yes, I have the following deficiencies / restrictions: ... .', zh: '你船有什么缺陷/限制吗？不，我船没有缺陷/限制。是的，我船有下述缺陷/限制'),
    MaritimePhrase(id: '1.3.22', category: 'movement', en: 'The maximum permitted draft is ... metres.', zh: '最大允许吃水是...米'),
    MaritimePhrase(id: '1.3.23', category: 'movement', en: 'Do you have any list? Yes, I have a list to port / starboard of ... degrees. No, I have no list.', zh: '你船有横倾吗？是的，我左/右倾...度。不，我没有横倾'),
    MaritimePhrase(id: '1.3.24', category: 'movement', en: 'Are you on even keel? Yes, I am on even keel. No, I am trimmed by the head / stern.', zh: '你船是平吃水吗？是的，我船是平吃水。不，我有首/尾倾'),
    MaritimePhrase(id: '2.1.1', category: 'broadcast', en: 'Winds, storms, tropical storms, sea state', zh: '风、暴风雨、热带风暴；海况P44'),
    MaritimePhrase(id: '2.1.1.1', category: 'broadcast', en: 'What is wind direction and force in your position / in position ... ? Wind direction ...(cardinal points), force Beaufort ... in my position /in position ... .', zh: '你处/...处的风力、风向怎样？我处/...处的风向为...（罗经点），风力为...（蒲氏）级'),
    MaritimePhrase(id: '2.1.1.2', category: 'broadcast', en: 'What wind is expected in my position / in position ... ? The wind in your position / in position ... is expected from direction... (cardinal points), force Beaufort ... .to increase / decrease variable.', zh: '我处/...处的风力、风向预计怎样？预计你处/...处的风向为...（罗经点），蒲氏风力为...。要增强/减弱。要变化'),
    MaritimePhrase(id: '2.1.1.3', category: 'broadcast', en: 'What is the latest gale / storm warning? The latest gale / storm warning is as follows:Gale / storm warning. Winds at ... local in area ... (met.area) from direction ...(cardinal points) and force Beaufort ... backing/veering to ...(cardinal points).', zh: '最新的大风/风暴警报怎样？最新的大风警报如下：大风警报。...当地时间在...区域（气象区域）风力（蒲氏）...级，风向从...（罗经点）逆转/顺转为...（罗经点）'),
    MaritimePhrase(id: '2.1.1.4', category: 'broadcast', en: 'What is the latest tropical storm warning? The latest tropical storm warning is as follows: Tropical storm warning at ... local. typhoon ... (name) with central pressure of ...millibars/hPascals located in position ... Present movement... (cardinal points) at ...knots. Winds of ... knots within radius of ... miles of centre.', zh: '最新的热带风暴警报怎样？最新热带风暴警报：...当地时间热带风暴警报。...（名称）台风中心气压...毫巴/百帕，位置在...。现在正以...节的速度向...（罗经点）移动。离中心...海里的范围内风速为...节'),
    MaritimePhrase(id: '2.1.1.5', category: 'broadcast', en: 'What is the atmospheric pressure in your position / in position ... ? The atmospheric pressure in my position / in position ... is ... millibars/hPascals.', zh: '你处/...处的气压是多少？我处/...处的气压为...毫巴/百帕'),
    MaritimePhrase(id: '2.1.1.6', category: 'broadcast', en: 'What is the barometric change in your position / in position ... ? The barometric change in my position / in position ...is ... millibars/hPascals per hour / within the last ... hours. The barometer is steady / dropping (rapidly) / rising (rapidly).', zh: '你处/...处的气压变化怎样？我处/...处在最近...小时内每小时气压变化...毫巴/百帕。气压计稳定/（急速）下降/（急速）上升'),
    MaritimePhrase(id: '2.1.1.7', category: 'broadcast', en: 'What maximum winds are expected in the storm area? Maximum winds of ... knots are expected ~ in the storm area. ~ within a radius of ... kilometres / miles of the centre. ~ in the safe / dangerous semicircle.', zh: '风暴区的最大风力预计为多少？最大风力预计为...节~在风暴区。~以风暴中心为圆心，半径为...公里/海里的范围内。~在安全/危险半圆内'),
    MaritimePhrase(id: '2.1.1.8', category: 'broadcast', en: 'What is sea state in your position / in position ... ? The smooth/moderate/rough/high sea/ slight/moderate/heavy swell in my position / in position ... is ... metres from... (cardinal points).', zh: '你处/...处的海况怎样？我处/...处小/中/大/狂浪/轻/中/狂涌，高...米，来自（罗经点）'),
    MaritimePhrase(id: '2.1.1.9', category: 'broadcast', en: 'Is the sea state expected to change ( - within the next hours)? No, the sea state is not expected to change (- within the next hours). Yes, a sea / swell of ... metres from ...(cardinal points)is expected (- within the next hours).', zh: '（在未来几小时内）海况预计会发生变化吗？不，（在未来几小时内）海况预计不会发生变化。是的，（在未来几小时内）预计高度为...米的浪/涌会从...方向来（罗经点）'),
    MaritimePhrase(id: '2.1.1.10', category: 'broadcast', en: 'A tsunami / an abnormal wave is expected by ... local.', zh: '预计在...当地时间有海啸/异常浪'),
    MaritimePhrase(id: '2.1.2.1', category: 'broadcast', en: 'What is visibility in your position / in position ... ? Visibility in my position / in position... is ... metres / nautical miles Visibility is restricted by mist / fog / snow / dust / rain. Visibility is increasing / decreasing / variable.', zh: '你处/...处的能见度怎样？我处/...处的能见度为...米/海里。霾/雾/雪/尘埃/雨限制了能见度。能见度正在变好/变差/时好时坏'),
    MaritimePhrase(id: '2.1.2.2', category: 'broadcast', en: 'Is visibility expected to change in my position / in position ... (within the next hours)? No, visibility is not expected to change in your position / in position...(- within the next hours). Yes, visibility is expected to increase / decrease to ... metres / nautical miles in your position / in position ... ( within the next hours). Visibility is expected to be variable between ... metres / nautic', zh: '（未来几小时内）我处/...处的能见度预计会发生变化吗？不，（在未来几小时内）你处/...处的能见度预计不会发生变化。是的，（在未来几小时内）你处/...处的能见度预计将增加/降低至...米/海里。（未来几小时内）你处/...处的能见度预计在...米/海里之间变化'),
    MaritimePhrase(id: '2.1.3.1', category: 'broadcast', en: 'What is the latest ice information? Ice warning. Ice / iceberg(s) located in position ... / reported in area around ... No ice located in position ... / reported in area around ... .', zh: '最新的冰况信息怎样？冰况警报。冰/冰山位于...位置/据报在...周围海域。在...位置/据报在...周围海域未发现冰'),
    MaritimePhrase(id: '2.1.3.2', category: 'broadcast', en: 'What ice situation is expected in my position / area around ... ? Ice situation is not expected to change in your position / area around ... . expected to improve / deteriorate in your position / area around ... . Thickness of ice is expected to increase / decrease in your position / area around ... .', zh: '我处/...周围海域的冰情预计会发生什么变化？你处/...周围海域的~预计不会发生变化。~预计会减轻/加重。你处/...周围海域的冰的厚度预计会增加/减少'),
    MaritimePhrase(id: '2.1.3.3', category: 'broadcast', en: 'Navigation is dangerous in area around ... due to floating ice / pack ice / iceberg(s).', zh: '由于浮冰/浮冰群/冰山，在...周围海域航行有危险'),
    MaritimePhrase(id: '2.1.3.4', category: 'broadcast', en: 'Navigation in area around ... is only possible for high-powered vessels of strong construction . with ice-breaker assistance.', zh: '只有大功率强结构的船只才可能在...周围海域航行。只有在破冰船的援助下才可能在...周围海域航行'),
    MaritimePhrase(id: '2.1.3.5', category: 'broadcast', en: 'Area around ... temporarily closed for navigation.', zh: '在...周围海域临时封航'),
    MaritimePhrase(id: '2.1.3.6', category: 'broadcast', en: 'Danger of icing in area around ... .', zh: '在...周围海域的海水有冰冻的危险'),
    MaritimePhrase(id: '2.1.4.1', category: 'broadcast', en: 'The present tide ... is metres above / below datum in position ... .', zh: '在...处现在的潮高高于/低于基准面...米'),
    MaritimePhrase(id: '2.1.4.2', category: 'broadcast', en: 'The tide ... is metres above/below prediction.', zh: '潮汐高于/低于预报...米'),
    MaritimePhrase(id: '2.1.4.5', category: 'broadcast', en: 'Abnormally high / low tides are expected in position ... at about ... local / within ...hours.', zh: '在...处大约在...当地时间/...小时内预计出现异常高/低潮'),
    MaritimePhrase(id: '2.1.4.6', category: 'broadcast', en: 'Is the depth of water sufficient in position ... ? Yes, the depth of water is sufficient in position ... . No, the depth of water is not sufficient in position ... . The depth of water is...metres in position ... .', zh: '在...处有足够的水深吗？是的，在...处有足够的水深。不，在...处没有足够的水深。在...处水深有...米'),
    MaritimePhrase(id: '2.1.4.7', category: 'broadcast', en: 'My draft ... is metres - can I enter / pass ... (charted name of place)? Yes, you can enter / pass (charted name of place). No, you cannot enter / pass (charted name of place) - wait until ... local.', zh: '我的吃水是...米，我能进入/通过...（海图上标示的地名）吗？是的，你能进入/通过...（海图上标示的地名）。不，你不能进入/通过...（海图上标示的地名），要等到...当地时间'),
    MaritimePhrase(id: '2.1.4.8', category: 'broadcast', en: 'The charted depth of water is increased / decreased by ... metres due to sea state / winds.', zh: '由于海况/风的影响，海图上标示的水深增加/减少...米'),
    MaritimePhrase(id: '2.2.1.1', category: 'broadcast', en: 'Defects ...( charted name of light / buoy) in position ... unlit / unreliable / damaged / destroyed / off station / missing.', zh: '故障.位置的...（海图上标示的灯标/浮标名）熄灭/不可靠/损坏/毁坏/移位/失踪'),
    MaritimePhrase(id: '2.2.1.2', category: 'broadcast', en: 'Alterations ( charted name of lightbuoy / buoy) in position ... ~ (temporarily) changed to ...(full characteristics). ~ (temporarily) removed. ~ (temporarily) discontinued.', zh: '变更在...位置的...（海图上标示的灯标/浮标名）~（临时）改变为...（全部特征）。~（临时）移开。~（临时）停止'),
    MaritimePhrase(id: '2.2.1.3', category: 'broadcast', en: 'New and moved ...( charted name of light / buoy) ...(full characteristics) ~ established in position ... . ~ re-established in position ... . ~ moved ... kilometres / nautical miles in ... (direction) to position ... .', zh: '新的和移动的...（海图上标示的灯标/浮标名）...（全部特征）~在...处设置。~在...处重设。~向...（方向）移动...公里/海里到...处'),
    MaritimePhrase(id: '2.2.1.4', category: 'broadcast', en: '(Note: Only for major fog signal stations.) Fog signal ...( charted name of light / buoy) in position ... inoperative.', zh: '（注：只限于主要雾号站）在...位置的（海图上标示的灯标/浮标名）雾号无效'),
    MaritimePhrase(id: '2.2.2.1', category: 'broadcast', en: 'Superbuoy / mine / unlit derelict vessel / ... (number) container(s) adrift in vicinity ...(position) at ...(date and time if known).', zh: '大型浮筒/水雷/无灯光显示的被弃船/...（数量）的集装箱在...（日期、时间，若知）在...（位置）附近漂流'),
    MaritimePhrase(id: '2.2.3.1', category: 'broadcast', en: 'GPS /GLONASS Satellite ...(number) unusable from ... (date and time) to ...(date and time). Cancel one hour after time of restoration....', zh: '（号）GPS/GLONASS卫星从...（日期和时间）到...（日期和时间）不能使用。恢复后1小时撤销'),
    MaritimePhrase(id: '2.2.3.2', category: 'broadcast', en: 'LORAN station ...(name or number of master / secondary) off air from ...(date and time) to... (date and time). Cancel one hour after time of restoration.', zh: '...（主/副台名称或者编号）罗兰台从...（日期和时间）到...（日期和时间）停止工作。恢复后1小时撤销'),
    MaritimePhrase(id: '2.2.3.3', category: 'broadcast', en: 'RACON ... (name of station) in position ... off air from ...(date and time) to... (date and time). Cancel one hour after time of restoration.', zh: '位于...处的...（台名）雷达信标从...（日期和时间）到...（日期和时间）停止工作。恢复后1小时撤销'),
    MaritimePhrase(id: '2.2.4', category: 'broadcast', en: 'Seabottom characteristics, wrecks Use REPORTED when position is unconfirmed, and use LOCATED when position has been confirmed by survey or other means', zh: '海底特征，沉船当位置无法经确定时，使用据报；当位置通过测量或其他方法得到确定时，使用据测。P50'),
    MaritimePhrase(id: '2.2.4.1', category: 'broadcast', en: 'Uncharted reef / rock / shoal / dangerous wreck / obstruction reported / located in position ... .', zh: '据报/据测在...处有海图上未标明的暗礁/礁石/浅滩/危险沉船/碍航物'),
    MaritimePhrase(id: '2.2.4.2', category: 'broadcast', en: 'Dangerous wreck in position... marked by ... (type)buoy ...(distance in kilometres/nautical miles ) ...(direction).', zh: '在...处有危险沉船，在其...（方向）...（距离，用公里/海里表示）处设有...（型）浮标'),
    MaritimePhrase(id: '2.2.5.1', category: 'broadcast', en: 'Cable, pipeline and seismic / hydrographic operations', zh: '电缆、管道铺设和地震/水道测量作业P51'),
    MaritimePhrase(id: '2.2.5.1.1', category: 'broadcast', en: 'Cable / pipeline operations by ... (vessel) in vicinity / along line joining ... (positions) from ...(date and time)to ...(date and time). Wide berth requested (if requested). Contact via VHF Channel ... (if requested).', zh: '电缆/管道铺设作业从...（日期和时间）到...（日期和时间）由...（轮）在...（位置）附近/沿...（位置）连线进行。（如果需要）请宽让。（如果需要）请用VHF...频道联系'),
    MaritimePhrase(id: '2.2.5.1.2', category: 'broadcast', en: 'Seismic survey / hydrographic operations by ...(vessel) from ...(date and time) to...(date and time) in ...(position). Wide berth requested. (if requested). Contact via VHF Channel ... (if requested).', zh: '地震/水道测量作业从...（日期和时间）到...（日期和时间）由...（轮）在...（位置）进行。（如果需要）请宽让。（如果需要）请用VHF...频道联系'),
    MaritimePhrase(id: '2.2.5.1.3', category: 'broadcast', en: 'Survey vessel ...(name) towing ...(length) seismic cable along line joining / in area bounded by / in vicinity ...(position) from ...(date and time) to ...(date and time). Wide berth requested (if requested). Contact via VHF Channel ... (if requested).', zh: '测量船...（船名）从...（日期和时间）到...（日期和时间）沿...（位置）连线/在以...（位置）为界的区域/在...（位置）附近拖带...（长度）的地震电缆。（如果需要）请宽让。（如果需要）请用VHF...频道联系'),
    MaritimePhrase(id: '2.2.5.1.4', category: 'broadcast', en: 'Current meters / hydrographic instruments moored in ...(position). Wide berth requested (if requested).', zh: '流速仪/水文测量仪表安放在...（位置）。（如果需要）请宽让'),
    MaritimePhrase(id: '2.2.5.2', category: 'broadcast', en: 'Diving, towing and dredging operations', zh: '潜水作业，拖带作业和疏浚作业P51'),
    MaritimePhrase(id: '2.2.5.2.1', category: 'broadcast', en: 'Diving/dredging operations by vessel ... (name) from ...(date and time) to ...(date and time) in position ... . Wide berth requested (if requested).', zh: '潜水作业/疏浚作业由...轮（名称）从...（日期和时间）到...（日期和时间）在...（位置）进行。（如果需要）请宽让'),
    MaritimePhrase(id: '2.2.5.2.2', category: 'broadcast', en: 'Difficult tow from ...(port of Departure) on ... (date to ...(destination)on ...(date). Wide berth requested.', zh: '困难拖带于...（日期）从...（出发港）于...（日期）到...（目的港），请宽让'),
    MaritimePhrase(id: '2.2.5.3.1', category: 'broadcast', en: 'Transhipment of ...(kind of cargo) in position... . Wide berth requested.', zh: '...（货物种类）转运作业在...处进行。请宽让'),
    MaritimePhrase(id: '2.2.5.3.2', category: 'broadcast', en: 'MT（name） ... spilling oil / chemicals /... in position....Wide berth requested.', zh: '油轮（名称）在...处溢出油/化学品.…请宽让'),
    MaritimePhrase(id: '2.2.5.3.3', category: 'broadcast', en: 'LNG-tanker(name) ... leaking gas in position... - do not pass to windward.', zh: '液化天然气船（船名）在...处泄漏气体。请勿在下风通过'),
    MaritimePhrase(id: '2.2.5.3.4', category: 'broadcast', en: 'Oil clearance operations near MT ... in position ... . Wide berth requested.', zh: '...油轮附近的清除油污作业在...处进行。请宽让'),
    MaritimePhrase(id: '2.2.5.4', category: 'broadcast', en: 'Off-shore installations, rig moves', zh: '近岸装置，钻井移动P52'),
    MaritimePhrase(id: '2.2.5.4.1', category: 'broadcast', en: 'Platform ...(name/number if available) reported / established in position... at ... (date and time).Wide berth requested (if requested).', zh: '在...（日期和时间）平台...（名称/号码，如果能提供的话）据报/设置在...处。（如果需要）请宽让'),
    MaritimePhrase(id: '2.2.5.4.2', category: 'broadcast', en: 'Platform ...(name/number if available) removed from ...(position) on ... (date).', zh: '平台...（名称/号码，如果能提供的话）已于...（日期）从...（位置）移开'),
    MaritimePhrase(id: '2.2.5.4.3', category: 'broadcast', en: 'Pipeline / platform ...(name/number if available) in position ... spilling oil / leaking gas. Wide berth requested.', zh: '管道/平台（名称/号码，如果能提供的话）在...处溢油/泄漏气体。请宽让'),
    MaritimePhrase(id: '2.2.5.4.4', category: 'broadcast', en: 'Derelict platform ...(name/number if available) being removed from ...(position) at ... (date and time).Wide berth requested.', zh: '被遗弃的平台...（名称/号码，如果能提供的话）于...（日期和时间）被从...（位置）移开。请宽让'),
    MaritimePhrase(id: '2.2.5.5', category: 'broadcast', en: 'Defective locks or bridges', zh: '有缺陷的船闸或桥P52'),
    MaritimePhrase(id: '2.2.5.5.1', category: 'broadcast', en: 'Lock /bridge...(name) defective. For entering ...(charted name of place) use lock ...(name). 2.5.5.2Avoid this area - no possibility for vessels to turn.', zh: '...（名称）船闸桥有缺陷。驶入...（海图上标示的地名）要使用...（名称）船闸。2.5.5.2避免该区域，船舶不可能在该处掉头'),
    MaritimePhrase(id: '2.2.5.6.1', category: 'broadcast', en: 'Gunnery / rocket firing / missile / torpedo / underwater ordnance exercises in area bounded by ... (positions) from ... (date and time) to... (date and time). Wide berth requested (if requested).', zh: '枪炮/火箭/导弹/鱼雷/水下武器演习从...（日期和时间）到...（日期和时间）在以...（位置）为界的区域内进行。（如果需要）请宽让'),
    MaritimePhrase(id: '2.2.5.6.2', category: 'broadcast', en: 'Mine clearing operations from ...(date time) to ...(date and time) in area bounded by ...(positions).Wide berth requested. Contact via VHF channel ...(number)(if requested).', zh: '扫雷作业从...（日期和时间）到...（日期和时间）在以...（位置）为界的区域内进行。请宽让。（如果需要）请用VHF...（数字）频道联系'),
    MaritimePhrase(id: '2.2.5.7.1', category: 'broadcast', en: 'Small fishing boats in area around ... - navigate with caution.', zh: '小渔船在...周围的区域。请谨慎驾驶'),
    MaritimePhrase(id: '2.2.5.7.2', category: 'broadcast', en: 'Is fishing gear ahead of me? No fishing gear ahead of you. Yes, fishing gear with buoys / without buoys in position .../ area around ... navigate with caution.', zh: '在我的前方有渔具吗？在你前方没有渔具。是的，带/不带浮标的渔具在...处/在...周围区域。请谨慎驾驶'),
    MaritimePhrase(id: '3.1', category: 'traffic', en: 'All accidents(dangerous) should be known and conformed', zh: '针对所有事故（险情）应了解和核实的情况P66'),
    MaritimePhrase(id: '3.1.1', category: 'traffic', en: 'What is your vessel’s name /call sigh /MMSI number? My vessel’s name is XXXX. My call sigh is XXXX. My MMSI number is XXXXXX.', zh: '你船的船名、呼号及海上移动业务识别码是什么？我船的船名是XXXX。我船的呼号是XXXX。我船的海上移动业务识别码是XXXXXX'),
    MaritimePhrase(id: '3.1.2', category: 'traffic', en: 'When and where did the accident happen? The accident happened in position XX degrees XX minutes North XXX degrees XX minutes East at XXXX local time/GMT. The accident happened in position bearing XXX degrees from XXXX lighthouse/ (lightbuoy, RACON etc.) distance X.X Nautical miles(cables, meters etc.) XX minutes ago.', zh: '何时何地发生事故？事故发生在当地时间/格林威治时间XXXX时，位置在北纬XX度XX分，东经XXX度XX分。XX分钟前，事故发生在视XXXX灯塔（灯浮/雷康等）方位XXX度距离X.X海里（链、米等）处'),
    MaritimePhrase(id: '3.1.3', category: 'traffic', en: 'Who is your owner/operator/agent in this port? My owner/operator/agent in this port is XXXXX.', zh: '你的船东/经营人/该港代理是谁？我的船东/经营人/该港代理是XXXXX'),
    MaritimePhrase(id: '3.1.4', category: 'traffic', en: 'How can I get connection with him? You can get connection with him by telephone. His telephone number is XXXXXXXX.', zh: '我如何可以跟他取得联系？你可以跟他通过电话取得联系。他的电话号码是XXXXXXXX'),
    MaritimePhrase(id: '3.1.5', category: 'traffic', en: 'What happened? I am / MV XXXX is on fire/aground/ flooding/sinking/disabled/ ....dragging/under attack by pirates ... . I have / MV XXXX has collided with MV XXXX. unknown vessel / object / ... . ...(name) light vessel. seamark ... (charted name). iceberg/ ... . I have/ MV XXXX has dangerous list to port /starboard. lost person in position ... .', zh: '发生了什么事？我（船）失火/搁浅/进水/正在下沉/失控等/走锚/遭到海盗袭击。我（船）与XXXX船不明船/不明物XX灯船XX（海图上名称）航标冰山等发生了碰撞。我（船）左/右倾，危险。在...位置人员落水'),
    MaritimePhrase(id: '3.1.6', category: 'traffic', en: 'What’s the number of persons on board? Number of persons on board: 25. Are there any passenger? No passenger on board. Number of passengers: five. Report injured persons. No persons injured. Number of injured persons / casualties: two.', zh: '你（船）在船人数多少？船上人员共25人。船上有旅客吗？船上没有旅客。船上有5名旅客。报告人员伤亡情况。没有人员伤亡。有2人受伤/死亡'),
    MaritimePhrase(id: '3.1.7', category: 'traffic', en: 'How many tons of cargo on board? XXX tons cargo on board. They are all general cargo/bulk cargo/containers/... . Are there any dangerous goods? No dangerous goods on board. XXX containers / barrels / drums / bags / tons/kilograms .... dangerous goods on board. What’s the IMO-Class? Their IMO-Class .... (i.e.4.1). What’s the UN-number? Their UN-number XXXX . Where are they loaded? They loaded in ho', zh: '船上载有多少吨货？船上载有XXX吨货。它们是杂货、散货、集装箱等。有否危险货物？船上没有危险货物。船上有XXX集装箱/桶/包/吨/公斤/....危险货物。它们属于哪类危险品？按《国际危规》划分，它们属于....类危险品（4.1类）。它们的联合国编号是多少？它们的联合国编号是XXXX。它们装在何处？它们装在第二货舱/甲板上'),
    MaritimePhrase(id: '3.2.1.8', category: 'traffic', en: 'What kind of assistance is required? I do not / MV ... does not require assistance. I require / MV ... requires fire fighting assistance. breathing apparatus - smoke is toxic. foam extinguishers / CO2 extinguishers. fire pumps. medical assistance /tug assistance ... .', zh: '你船需要得到何种援助？P72我（船）不需要援助。我（船）需要消防援助。呼吸装置（烟雾有毒）。泡沫灭火器/二氧化碳灭火器。消防水泵。医疗援助/拖轮援助等'),
    MaritimePhrase(id: '3.2.1.9', category: 'traffic', en: 'What’s the acting you are taking? I am / MV XXXX is taking all necessary actions to control the development of the fire. Advice: Close all openings and ventilator(s) in fire area. Remove all flammable goods in vicinity to separate from the fire area. Turn bow / stern / port side / starboard side to windward.', zh: '你（船）正在采取什么措施？我（船）正在采取一切必要措来控制火势的发展。建议：关闭火区内的所有开口和通风装置。移开附近的易燃物品，隔离火区。将船首/船尾/左舷/右舷摆在下风'),
    MaritimePhrase(id: '3.2.1.10', category: 'traffic', en: 'Is the fire extinguished? Yes, fire (in ... ) extinguished. No, fire (in ... ) not extinguished (yet). Fire restricted to ... space / area.', zh: '火熄灭了吗？是的，火熄灭了。火还没有熄灭。火已被限制在...范围内'),
    MaritimePhrase(id: '3.2.1.11', category: 'traffic', en: 'Advice: Check the fire area every ... minutes / hour(s) for re-ignition .', zh: '建议：每...分钟／小时要检查一次火区以防“死灰复燃”'),
    MaritimePhrase(id: '3.2.2.1', category: 'traffic', en: 'Is the flooding under control? Yes, flooding is under control. No, flooding is not under control. I / MV ... cannot control flooding.', zh: '进水能得到控制吗？是，进水能得到控制。不，进水不能得到控制。我（船）无法控制进水'),
    MaritimePhrase(id: '3.2.2.2', category: 'traffic', en: 'Is danger imminent ? No, danger not imminent. Yes, danger of (total) blackout (in ...). Yes, danger of heavy listing / capsizing / sinking / ... .', zh: '很危急吗？不，不很危急。是的，全船已失电。是的，我船横倾严重／正在倾覆／正在下沉等'),
    MaritimePhrase(id: '3.2.2.3', category: 'traffic', en: 'What part of your vessel is flooding? Engine-room/ hold No.3/fore peak tank/ bottom/... is flooding.', zh: '船上什么部位进水？机舱/第三货舱/首尖舱/船底/...进水'),
    MaritimePhrase(id: '3.2.2.4', category: 'traffic', en: 'What’s the size of flooding point? The size of flooding point is XX meters by XX meters. About XX square meters.', zh: '进水点的尺寸？进水点的尺寸是XX米乘XX米,约XX平方米'),
    MaritimePhrase(id: '3.2.2.5', category: 'traffic', en: 'What’s the shape of flooding point? The sharp of flooding point is triangle/circle/semicircle/oval/... .', zh: '进水点的形状？进水点的形状是三角形的/圆形的/半圆形的/隋圆形的等'),
    MaritimePhrase(id: '3.2.2.6', category: 'traffic', en: 'What’s the height of flooding point? The height of flooding point is 2 meters below water line. 8 meters from base line. near the water line/light load line.', zh: '进水点的高度？进水点在水线以下2米处。在（龙骨）基线以上8米处。在水线（轻载水线）附近'),
    MaritimePhrase(id: '3.2.2.7', category: 'traffic', en: 'What kind of assistance is required? I require / MV ... requires ~pumps /divers/collision mats /timberwedges/leaking stopper/...tug assistance to beach. ~some barge to transfer cargo. ~escort. ~assistance to stop flooding from outside. I will send pumps / divers / timber wedges/ collision mats ... . I cannot send pumps / divers ..., because they are not available at present.', zh: '你船需要得到何种援助？我（船）需要~水泵/潜水员/堵漏毯/木楔/堵漏器材拖轮协助冲滩等。~一些船驳来转运货物。~护航。~援助以便从舷外实施堵漏。我将（给你）送水泵/潜水员/木楔/堵漏毯等。由于目前没有现成的水泵/潜水员等，我不能送来'),
    MaritimePhrase(id: '3.2.2.8', category: 'traffic', en: 'What’s the condition of your vessel? I have / MV ... has dangerous list to port / starboard side about ten degrees. I am / MV ... in critical condition.', zh: '你船状况怎样？我（船）左/右倾10度，比较危险。我船情况危急'),
    MaritimePhrase(id: '3.2.2.9', category: 'traffic', en: 'What’s the maximum flooding rate of your vessel? About 200 tons per hour. What is the discharging rate of your vessel? About 150 tons per hour. How much water is in the vessel at present? Quantity of water (in ...) about ... tons. Quantity of water (in ...) is increasing.', zh: '你船的最大进水速度多少？大约每小时２００吨。你船排水速度多少？大约每小时１５０吨。目前船上有多少水？在...位置大约有...吨水。在...位置的水量还在增加'),
    MaritimePhrase(id: '3.2.2.10', category: 'traffic', en: 'Can you proceed without assistance? Yes, I / MV XX can proceed without assistance. No, I / MV XX requires tug assistance /...', zh: '你在没有外界协助的情况下能（安全）行驶吗？是，我（船）可以安全行驶。不，我（船）需要拖轮协助'),
    MaritimePhrase(id: '3.2.2.11', category: 'traffic', en: 'What’s the action you are taking? I am/ MV ...is discharging/pumping out water. I am/ MV ...is stopping flooding. I am/ MV ...is transferring goods to barges.', zh: '你（船）正在采取什么措施？我（船）正在排水。我（船）正在堵漏。我正在将货物驳卸至驳子上'),
    MaritimePhrase(id: '3.2.2.12', category: 'traffic', en: 'What’s the result of rescue? The result of rescue is negative. The result of rescue is unordinary.', zh: '救助效果如何？救助无效。救助效果显著'),
    MaritimePhrase(id: '3.2.2.13', category: 'traffic', en: 'Has flooding stopped ? Yes, flooding (in ...) has stopped. No, flooding (in ...) has not (completely) stopped (yet).', zh: '堵漏有效吗？是的，位于...位置的进水已被堵住。不，位于...位置的进水还没有被（完全）堵住'),
    MaritimePhrase(id: '3.2.2.14', category: 'traffic', en: 'Is flooding under control ? Yes, flooding (in ...) under control. Flooding (in ...) below / above capacity of (bilge) pump(s). Flooding restricted to ... space / area.', zh: '进水能得到控制吗？是的，位于...处的进水已得到控制。进水速度低于／超过（污）水泵的排水能力。进水已被限制在...区域'),
    MaritimePhrase(id: '3.2.2.15', category: 'traffic', en: 'Advice: Steer ... degrees to make a lee for the flooding point. Reduce your speed /Stop engines. Keep the sea on your port quarter / starboard quarter. Stiffen the bulkhead in vicinity. Check the condition of the vessel frequently.', zh: '建议：改驶航向XX度，将进水点摆在下风位置。减速/停车。保持左/右舭部受浪。加固附近舱壁。时刻察看船舶状况'),
    MaritimePhrase(id: '3.2.3.1', category: 'traffic', en: 'What part of your vessel collided? The hull/the bow/the bridge/ ... of my vessel collided.', zh: '碰撞部位？我船船体/船首/驾驶台...被撞'),
    MaritimePhrase(id: '3.2.3.2', category: 'traffic', en: 'What’s the damage. My hull/the bow/the bridge/ ... damaged severely. My topside strake/ My port side plating/ My bulwark/ My bilge strake/ ... at/near No.2 hold dent/torn about XX square meters. My shell plating at frame No. XX to XX about XX square meters deformed/bended severely, the maximum depth about XXX mm. 4 pieces air pipe and 5pieces sounding pipe of the No.3 water ballast tank broken. I ', zh: '损失情况如何？我船船体/船首/驾驶台受损严重。我船第二货舱部位/第二货舱附近舷顶列板/左舷舷板/舷墙/舭部列板约有XX平方米凹陷/撕裂。位于XX肋位至XX肋位间的外板约有XX平方米严重变形/凹陷，最大凹陷深度约XXX毫米第三压载水舱上的4个空气管和5个测量管破损。我船失控。我船正在进水'),
    MaritimePhrase(id: '3.2.3.3', category: 'traffic', en: 'What’s the condition of the collision bulkhead? The collision bulkhead of my vessel damaged. The collision bulkhead of my vessel no damaged. She is watertight.', zh: '船上防撞舱壁的状况如何？我船的防撞舱壁已损坏。我船的防撞舱壁没有损坏，可以保证水密'),
    MaritimePhrase(id: '3.2.3.4', category: 'traffic', en: 'Can you repair damage by yourself? Yes, I / MV XX can repair damage by myself. No, I / MV XX cannot repair damage by myself.', zh: '损坏部分你能自己修复吗？是的，我能自己修复。不，我不能靠自己修复'),
    MaritimePhrase(id: '3.2.3.5', category: 'traffic', en: 'Can you proceed by yourself? Yes, I / MV XX can proceed by myself. I / MV XX can only proceed at slow speed. No, I / MV XX can not proceed by myself.', zh: '你能自己航行吗？是的，我（船）能自己航行。我（船）只能慢速航行。不，我（船）不能靠自己航行'),
    MaritimePhrase(id: '3.2.3.6', category: 'traffic', en: 'What’s the name of another vessel involved collision? The name of another vessel involved collision is XX. What’s the condition of the another vessel involved collision？ She is damaged severely too. She is sinking. She is damaged slightly. She is no damaged.', zh: '另一碰撞船的船名是什么？另一碰撞船的船名是XX。另一碰撞船的状况如何？她同样受损严重。她正在下沉。她受损轻微。她没有受损'),
    MaritimePhrase(id: '3.2.3.7', category: 'traffic', en: 'Have you called her to rescue you? Yes, I have called her. She is rescuing me. She is anchoring nearby. She has escaped to outside/northward/westward... . No, I have not called her.', zh: '你有没有召唤她来救你？是的，我已召唤她来。她正在救我。她在（我船）附近锚泊。她已向外/向北/向西方向逃逸。不，我没有叫她'),
    MaritimePhrase(id: '3.2.3.8', category: 'traffic', en: 'What kind of assistance is required? I require / MV ... requires / escort / tug assistance /... .', zh: '你需要何种援助？我（船）需要护航/拖轮援助等'),
    MaritimePhrase(id: '3.2.3.9', category: 'traffic', en: 'Attention: Difficult tow from ... to ... wide berth requested. Hampered vessel in position ... area ... (course ... degrees, speed ... knots).', zh: '注意：从...拖往...，拖带困难—保持宽让。位于...位置处的不得被妨碍船舶的航向...度，航速...节'),
    MaritimePhrase(id: '3.2.4.1', category: 'traffic', en: 'What part of your vessel is aground? Aground forward / amidships /aft / full length. I can not establish which part is aground.', zh: '你船哪部分搁浅？船首/船中/船尾/全船搁浅。我不能确定哪部分搁浅'),
    MaritimePhrase(id: '3.2.4.2', category: 'traffic', en: 'What is your draft forward / aft before aground? My draft forward / aft is ... meters before aground. What is your present maximum draft ? My present maximum draft is ... meters. What is your freeboard? My freeboard is ... meters.', zh: '搁浅前你船的首尾吃水？搁浅前我船的首尾吃水是...。你现在的最大吃水是多少？目前我船的最大吃水是...米。你船干舷多少？我船干舷...米'),
    MaritimePhrase(id: '3.2.4.3', category: 'traffic', en: 'What’s the condition of the inner bottom plating? The condition of the inner bottom plating is OK. The sounding of the No.3 water ballast tank(port/starboard)/bilge tank is no change. The condition of the inner bottom plating is not OK. The sounding of the No.3 water ballast tank(port/starboard)/bilge tank is increasing.', zh: '你船内底板状况如何？我船内底板状况正常。第三压载水舱（左/右）/污水井的水位没有变化。我船内底板状况不正常。第三压载水舱（左/右）/污水井的水位正在增加'),
    MaritimePhrase(id: '3.2.4.4', category: 'traffic', en: 'What’s the damage？ No damage. Crack(s) in plating / No. ... double bottom / No. ... hold(s) / tank(s) /main/auxiliary engine(s) foundation / ... . Deformation(s) / indentation(s) to plating', zh: '损失情况？没有损失。外板／第...压载水舱／第...货舱／油舱／主辅机底座...裂开。外板变形、凹陷'),
    MaritimePhrase(id: '3.2.4.5', category: 'traffic', en: 'Check flooding . No flooding. Flooding in ... .', zh: '察看进水情况。没有进水。在...部位进水'),
    MaritimePhrase(id: '3.2.4.6', category: 'traffic', en: 'Is danger imminent ? No, danger not imminent. Yes, danger of heavy listing (to port / starboard) decreasing stability. damage by sea. breaking apart. environmental pollution.', zh: '情况危急吗？不，不危急。是的，有船舶严重左／右倾的危险。有船舶稳性减少的危险。有浪损的危险。有散架的危险。有环境污染的危险'),
    MaritimePhrase(id: '3.2.4.7', category: 'traffic', en: 'What is nature of sea bottom ? Sea bottom rocky. Sea bottom soft.', zh: '底质怎样？岩石底。软底'),
    MaritimePhrase(id: '3.2.4.8', category: 'traffic', en: 'What is the distribution of cargo? No. ... hold(s) / tank(s) ... tons (of ... cargo). Deck cargo forward / aft / amidships ... tons (of ...). Fore / after peak tank ... tons. No. ... double bottom tank(s) ... tons (of ballast / ...).', zh: '货物的分配情况如何？第...货舱／油舱...吨货物。甲板货船首／船尾／船中...吨。首／尾尖舱有...吨。第...双层底内有...吨压载'),
    MaritimePhrase(id: '3.2.4.9', category: 'traffic', en: 'What kind of assistance is required? I require / MV ... requires tug assistance / pumps / ... .', zh: '你需要何种援助？我（船）需要拖轮援助/水泵等'),
    MaritimePhrase(id: '3.2.4.10', category: 'traffic', en: 'What’s the action you will take? I / MV ... will jettison cargo to re-float. Warning! Do not jettison IMO-Class cargo! I / MV ...will transfer (deck) cargo from no.... hold(s) / tank(s) to no. ...hold(s) / tank(s). I / MV ...will transfer ballast / ... from no. ... double bottom tank(s) to no. ... double bottom tank(s). I / MV ...will pump out/fill in fore / after peak tank. Warning: Free surface ', zh: '你将采取何种措施？我（船）将通过抛货来起浮。警告：不要抛《国际危规》所列的危险货物！我（船）将甲板货从...舱（柜）转运/驳至...舱（柜）。我（船）将调整压载水，从...压载水舱驳至...压载水舱。我（船）将排出首/尾尖舱的水/注入水至首/尾尖舱。警告：在排放过程中要考虑自由液面（的影响）'),
    MaritimePhrase(id: '3.2.4.11', category: 'traffic', en: 'When do you / does MV ... expect to re-float? I expect / MV ... expects to re-float at ... UTC. when tide rises. when weather improves. when draft decreases. with tug assistance / ... .', zh: '你（船）准备何时起浮？我（船）准备在格林威治时间...点起浮。在涨潮时起浮。在天气转好时起浮。在吃水减少时起浮。通过拖轮协助起浮'),
    MaritimePhrase(id: '3.2.4.12', category: 'traffic', en: 'The tide is rising, it is ... hours before high water / after low water. it is ... meters below high water / above low water. The tide is falling, it is ... hours after high water / before low water. it is ... meters below high water / above low water. The tide is slack. Present tide is ... meters above / below datum ... in position ... .. The tide is ... meters above / below prediction. The tide ', zh: '正在涨潮，现在是高潮前/低潮后...小时。水位是在高潮潮面以下/低潮潮面以上...米。正在落潮，现在是高潮后/低潮前...小时。水位是在高潮潮面以下/低潮潮面以上...米。平潮。在...处现在的潮高是在基准面以上/下...米。潮位高于/低于预报...米。流向是...度。由于风/海况影响，海图水深增加/减少...米'),
    MaritimePhrase(id: '3.2.4.13', category: 'traffic', en: 'Has vessel re-floated? Yes, vessel re-floated. Can I proceed with voyage? No, Request a (diving) survey is necessary before sailing due to aground. No, vessel not re-floated (yet). Can you / can MV ... beach? I / MV ... can / will beach in position ... . I / MV ... cannot beach.', zh: '你船已起浮了吗？是的，我船已起浮。我能继续航行吗？不。由于搁浅你船开航前申请（船底）检验是必要的。不，我船尚未起浮。你（船）能冲滩吗？我（船）可以/将在...处冲滩。我（船）不能冲滩'),
    MaritimePhrase(id: '3.2.4.14', category: 'traffic', en: 'Advice: You should take all necessary actions to make fast the vessel after beaching.', zh: '建议：冲滩（成功）后，你应该采取所有必要的措施来固定船体'),
    MaritimePhrase(id: '3.2.4.15', category: 'traffic', en: 'Is vessel (still) making way ? Yes, vessel making way ahead / astern. No, vessel not making way.', zh: '你船还在航行吗？是的，我船正在向前行进／向后退。不，我船没在航行'),
    MaritimePhrase(id: '3.2.5.1', category: 'traffic', en: 'What’s condition of you/your vessel at present? I am / MV ... in danger of capsizing (- list increasing). I have / MV ... has dangerous list to port / starboard of XX degrees .', zh: '目前你（船）状况如何？我（船）横倾加剧，有倾覆危险。我（船）已左倾/右倾XX度，比较危险'),
    MaritimePhrase(id: '3.2.5.2', category: 'traffic', en: 'What’s the action will you take? I / MV ... will transfer cargo / bunkers to stop listing. jettison cargo to stop listing. pump into/out ballast water to against list.', zh: '你将采取什么措施？我（船）将通过驳运货物/燃油来制止横倾。抛货来制止横倾。泵入/排出压载水来阻止横倾'),
    MaritimePhrase(id: '3.2.5.3', category: 'traffic', en: 'Attention: Transhipment of ...(kind of cargo) in position ... - wide berth requested.', zh: '在...位置处有船正在驳运...（货种），所有船舶保持宽让'),
    MaritimePhrase(id: '3.2.6.1', category: 'traffic', en: 'What’s condition of you/your vessel? I am / MV ... sinking after collision / grounding / flooding / explosion / .…', zh: '你（船）的状况如何？我（船）因碰撞、搁浅、进水、爆炸等船体正在下沉'),
    MaritimePhrase(id: '3.2.6.2', category: 'traffic', en: 'What’s the action you are taking? I am / MV ...pumping out the water.', zh: '你正在采取什么措施？我（船）正在采取向外排水措施'),
    MaritimePhrase(id: '3.2.6.4', category: 'traffic', en: 'Advice: Check the situation of your vessel frequently. All life boat should be stand by ! Everybody should be on life jacket! All persons should stand by evacuation station.', zh: '建议：密切关注船舶状况。所有救生艇均应做好释放前的准备工作。所有人员均应穿好救生衣。所有人员应做好随时撤离的准备'),
    MaritimePhrase(id: '3.2.7', category: 'traffic', en: 'Disabled and adrift (Technical failure)', zh: '失控、漂流、机械故障P88'),
    MaritimePhrase(id: '3.2.7.1', category: 'traffic', en: 'What’s condition of you/your vessel? I am / MV ...not under command/adrift/drifting at ... knots to ... (cardinal points)/drifting into danger. Warning: Uncharted rocks in position ... . Risk of grounding at low water. The shallow water is ahead of you!', zh: '你（船）的状况如何？:我（船）失控/随波漂流/正向...（方位）漂移，速度...节/正在漂向危险中。警告：在...位置存有海图上未标明的岩石。低潮时（你船）有搁浅危险。你（船）前方是浅水区'),
    MaritimePhrase(id: '3.2.7.2', category: 'traffic', en: 'What problems do you have / does MV ... have? I have / MV ... has problems with engine(s) / steering gear / propeller / ... . I am / MV ...is maneuvering with difficulty. Attention: MV ... is not under command. Keep clear of her . Navigate with caution.', zh: '你（船）有什么故障吗？我（船）主机/舵机/推进器...故障。我（船）操纵困难。注意：...船失控，附近船舶）远离，谨慎航行'),
    MaritimePhrase(id: '3.2.7.3', category: 'traffic', en: 'What kind of assistance is required? I require / MV ... requires tug assistance.', zh: '你（船）需要何种援助？我（船）需要拖轮协助'),
    MaritimePhrase(id: '3.2.7.4', category: 'traffic', en: 'Do you require escort? No, I do not require / MV ... does not requires escort. Yes, I require / MV ... requires escort.', zh: '你船需要护航吗？不，我（船）不需要护航。是的，我（船）需要护航'),
    MaritimePhrase(id: '3.2.7.5', category: 'traffic', en: 'Can you repair by yourself? Yes, I can. No, I require / MV ... requires helicopter assistance. My owner has prepared with some spare parts for me.', zh: '你能自己修复吗？是的，我能自己修理。不，我（船）需要直升机援助。我的船东已为我准备好了一些备件'),
    MaritimePhrase(id: '3.2.7.6', category: 'traffic', en: 'When will the repair be finished? The repair will be finished in an hour. The repair will be finished soon, if the necessary spares is available. Warning. The weather will get worse within the next six hours. Force of wind is excepted to be increase in your position/area round.…', zh: '你船何时能够修复？修理将在1个小时内完成。如果备件到位的话，修理将很快完成。警告：天气在未来6小时内将变坏。你船位/船位附近处的风力预期将增加'),
    MaritimePhrase(id: '3.2.7.7', category: 'traffic', en: 'Stand by on VHF Channel ... / frequency ... . Standing by on VHF Channel ... / frequency ... .', zh: '你船应在VHF...频道/...频率上保持守听。我船正在VHF...频道/...频率上保持守听'),
    MaritimePhrase(id: '3.2.8.1', category: 'traffic', en: 'What problem do you/does your vessel have? I am / MV ... was under attack by pirates.', zh: '你船有什么问题？我（船）已被海盗袭击'),
    MaritimePhrase(id: '3.2.8.2', category: 'traffic', en: 'What is your present course and speed? My present course ... degrees, my speed ... knots.', zh: '你（船）现在的航向、航速？我（船）现在的航向...度，航速...节'),
    MaritimePhrase(id: '3.2.8.3', category: 'traffic', en: 'What kind of assistance is required? I require / MV ... requires medical assistance. navigational assistance. military assistance. tug assistance. escort / ... .', zh: '你（船）需要什么援助？我（船）需要医疗援助。导航援助。军事援助。拖轮援助。护航等援助'),
    MaritimePhrase(id: '3.2.8.4', category: 'traffic', en: 'Report damage. I have / MV .. has no damage. damage to navigational equipment . I am / MV ... not under command.', zh: '报告损坏情况。我（船）没有损坏。航海仪器有损坏。我（船）失控'),
    MaritimePhrase(id: '3.2.8.5', category: 'traffic', en: 'Can you / can MV ... proceed? Yes, I / MV ... can proceed. No, I / MV ... cannot proceed.', zh: '你船还能继续航行吗？是的，我船能继续航行。不，我船不能继续航行'),
    MaritimePhrase(id: '3.2.9.1', category: 'traffic', en: 'I have / MV ... has problems with cargo / engine(s) / navigation / ... .', zh: '我（船）货物/机器/航行等有有问题'),
    MaritimePhrase(id: '3.2.9.3', category: 'traffic', en: 'In what position will the tug(s) meet me? The tug(s) will meet you in position ... at ...UTC. Wait for the tug(s) in position ... .', zh: '拖轮将在什么位置与我会合？拖轮将于格林威治时间...时在...处与你会合。你船应在...处等拖轮'),
    MaritimePhrase(id: '3.2.9.4', category: 'traffic', en: 'Must I use the towing lines of my vessel? Yes, you must use the towing lines. No, you must use the towing lines of the tug.', zh: '我必须用我船的拖缆吗？是的，你必须用你船的拖缆。不，你必须用拖轮的拖缆'),
    MaritimePhrase(id: '3.2.10.1', category: 'traffic', en: 'I / crew of MV ... must abandon vessel ... after explosion / collision / grounding / flooding / piracy / armed attack', zh: '在爆炸/碰撞/搁浅/进水/被海盗抢劫/被武装袭击/...之后，我（船）必须弃船'),
    MaritimePhrase(id: '3.2.10.2', category: 'traffic', en: 'How many lifeboats / life crafts (with how many persons) will you launch? I will launch ... lifeboats / life crafts (with ... persons).', zh: '你船将释放多少救生艇/救生筏（可乘坐多少人）？我船将释放...艘救生艇/救生筏（可乘坐...人）'),
    MaritimePhrase(id: '3.2.10.3', category: 'traffic', en: 'How many persons will stay on board? No person will stay on board.', zh: '有多少人将呆在船上？没有人将会呆在船上'),
    MaritimePhrase(id: '3.2.10.4', category: 'traffic', en: 'Instruction: All sea chests and valves of oil pipes should be closed before evacuation if possible.', zh: '指令：如果可能的话，在人员撤离前应将所有海底阀和油路阀门关闭'),
    MaritimePhrase(id: '3.2.11.1', category: 'traffic', en: 'I have / MV ... has lost person overboard in position ... . Where did the person overboard from? The person overboard from the poop deck/the main deck.', zh: '我（船）有人落水，位置在...。人员从何处落水？人员从尾甲板/主甲板落水'),
    MaritimePhrase(id: '3.2.11.2', category: 'traffic', en: '“Sea patrol XXX”/rescue boat is proceeding to you for assistance - ETA at ... UTC / within ... hours. Stop in present position. Switch on the bow / stern search light. Hoist flag signal “Oscar”. All vessels in vicinity of position ... keep sharp lookout .', zh: '“海巡XXX”/搜救船正前来你处救助。预计在格林威治时间...时/在...小时内抵达你处。停在原处。开启船首/船尾搜救灯。悬挂信号旗“O”。在...位置处附近的所有船舶均应保持正规了望'),
    MaritimePhrase(id: '3.2.11.3', category: 'traffic', en: 'I am / MV ... is searching in vicinity of position ... . Aircraft ETA at ... UTC / within ... hours to assist in search.', zh: '我（船）正在...位置处附近进行搜寻。飞机将在格林威治时间...时/在...小时内抵达以协助搜寻'),
    MaritimePhrase(id: '3.2.11.4', category: 'traffic', en: 'Can you continue search? Yes, I can continue search. No, I cannot continue search.', zh: '你能继续搜寻吗？是的，我能继续搜寻。不，我不能继续搜寻'),
    MaritimePhrase(id: '3.2.11.5', category: 'traffic', en: 'What is the result of search? The result of search is negative. I / MV ... located / picked up person(s) in position ... . Person picked up is crewmember / passenger of MV ... .', zh: '搜寻结果如何？搜寻无效。我（船）在...位置处找到/救捞起落水人员。被救起的人员是...轮的船员/旅客'),
    MaritimePhrase(id: '3.2.11.6', category: 'traffic', en: 'What is condition of person(s)? Condition of person(s) bad / good. Person(s) dead/is injured/is suffering a shock/has hypothermia.', zh: '落水人员的情况怎样？落水人员的情况不好/良好。落水人员死亡/受伤/受了惊吓/体温过低.'),
    MaritimePhrase(id: '3.2.11.7', category: 'traffic', en: 'Stop search. Return to ... . Proceed with your voyage.', zh: '停止搜救。返回...。你（船）继续航行'),
    MaritimePhrase(id: '3.2.12.1', category: 'traffic', en: 'I require / MV ... requires medical assistance.', zh: '我（船）需要医疗援助'),
    MaritimePhrase(id: '3.2.12.2', category: 'traffic', en: 'What kind of assistance is required? I require / MV ... requires boat for hospital transfer. radio medical advice. helicopter with doctor (to pick up person(s).', zh: '你需要何种援助？我（船）需要小艇以便将人员转送医院。无线电医疗指导。有医生的直升机（接送人员）'),
    MaritimePhrase(id: '3.2.12.3', category: 'traffic', en: 'I will send boat to transfer doctor. send helicopter with doctor. send helicopter to pick up person(s)/transfer doctor. arrange for radio medical advice on VHF Channel ... / frequency ... .', zh: '我将派出小艇。派出有医生的直升机。派出直升机接送人员/接送医生。在VHF...频道/...频率安排无线电医疗咨询'),
    MaritimePhrase(id: '3.2.12.4', category: 'traffic', en: 'What’s the ETA of the boat / helicopter you just sent? The boat / helicopter ETA at ... UTC / within ... hours.', zh: '你刚派出的小艇/直升机预计抵达时间？预计小艇/直升机将在格林威治时间...时/在...小时内抵达'),
    MaritimePhrase(id: '3.2.12.5', category: 'traffic', en: 'Do you have doctor on board? Yes, I have doctor on board. No, I have no doctor on board.', zh: '船上有医生吗？是的，船上有医生。不，船上没有医生'),
    MaritimePhrase(id: '3.2.12.6', category: 'traffic', en: 'Can you make rendezvous in position ... ? Yes, I can make rendezvous in position at ... UTC / within ... hours. No, I cannot make rendezvous.', zh: '你能在...位置会合吗？是的，我能在格林威治时间...时/在...小时内在...位置会合。不，我不能会合'),
    MaritimePhrase(id: '3.2.12.7', category: 'traffic', en: 'Can you transfer doctor(s) to my vessel by boat / helicopter. Transfer of person(s) not possible.', zh: '你能用小艇/直升机将医生接送至我船？无法转运人员'),
    MaritimePhrase(id: '3.2.13.1', category: 'traffic', en: 'I have / MV has lost dangerous goods of IMO-Class ... in position ... I am / MV ... is dangerous source of radiation.', zh: '我（船）在...位置丢失了IMO...类危险品。我（船）有危险辐射源'),
    MaritimePhrase(id: '3.2.13.2', category: 'traffic', en: 'How many dangerous goods overboard? XX containers / barrels / drums / bags / ... with dangerous goods of IMO-Class ... overboard. They adrift near position ... .', zh: '有多少危险货物入海？XX装有IMO...类危险品的集装箱/桶/包/...入海。它们在...位置附近漂流'),
    MaritimePhrase(id: '3.2.13.3', category: 'traffic', en: 'Advice: Turn the vessel out of the wind . Put on protective clothing and breathing apparatus.', zh: '建议：将船转向至（危险货物的）上风。穿上保护服，戴上呼吸装置'),
    MaritimePhrase(id: '3.2.14.1', category: 'traffic', en: 'I am / MV ... is spilling crude oil /fuel oil/diesel oil/gasoline/ ... in position ... . I have / MV ... has accidental spillage of oil', zh: '我（船）在...位置溢出原油/燃油/柴油/汽油...。我（船）发生事故性溢油'),
    MaritimePhrase(id: '3.2.14.2', category: 'traffic', en: 'Can you / MV ... stop spillage? Yes, I / MV ... can stop spillage. No, I / MV ... cannot stop spillage.', zh: '你（船）能控制住溢油吗？是的，我（船）能控制住溢油。不，我（船）不能控制住溢油'),
    MaritimePhrase(id: '3.2.14.3', category: 'traffic', en: 'How many tons/kilograms/liters of crude oil /fuel oil/diesel oil/gasoline/ ...overboard? XX tons/kilograms/liters of crude oil /fuel oil/diesel oil/gasoline/ ...overboard. I have / MV ... has danger of pollution.', zh: '多少吨/公斤/公升原油/燃油/柴油/汽油...入海？XX吨/公斤/公升原油/燃油/柴油/汽油...入海。我（船）有污染危险'),
    MaritimePhrase(id: '3.2.14.4', category: 'traffic', en: 'What’s the spilling oil type and Redwood number? The spilling oil type is ..., Redwood number is.…', zh: '你船溢油的种类及雷氏粘度号？我船溢油的种类是...，雷氏粘度号是...'),
    MaritimePhrase(id: '3.2.14.5', category: 'traffic', en: 'What kind of assistance is required? I require / MV… requires oil clearance assistance. floating booms / oil fences/oil dispersants. guard boat. Instruction: You must have permission before using oil dispersants. Stay in vicinity of pollution and co-operate with oil clearance team. Attention: Oil clearance operations near MT ...in position ...—wide berth requested.', zh: '你船需要何种援助？我（船）需要油污清除援助。浮栅/围油栏/消油剂。警戒船。指令：使用消油剂必须得到许可。停留在污染区附近，与清污队合作清污。注意：位于...位置处的...油轮附近正在进行清除油污作业，所有途经船舶保持宽让'),
    MaritimePhrase(id: '3.2.14.6', category: 'traffic', en: 'What’s the action you are taking? I am / MV ... is taking actions according to my OIL POLLUTION PREVENTION EMERGENCY PLAN to stop the spillage.', zh: '你正在采取什么清污措施？我（船）正在按照我（船）的应急油污计划制止油污溢出'),
    MaritimePhrase(id: '3.2.14.7', category: 'traffic', en: 'Is the oil pollution prevention plan available ? Yes, the oil pollution prevention plan is available. No, the oil pollution prevention plan is not available (yet).', zh: '防止油污计划可用吗？是的，防止油污计划可供使用。不，还没有防止油污计划可供使用'),
    MaritimePhrase(id: '3.2.14.8', category: 'traffic', en: 'Report: Located oil spill in position ... extending ... (length and width in meters)to ... (cardinal points). Located oil spill in the wake of MV ... .', zh: '报告：发现位于...处的溢油向...（罗经点）延伸...（用米表示的长度和宽度）。发现油类溢出在...船的尾迹中'),
    MaritimePhrase(id: '3.2.14.9', category: 'traffic', en: 'Can you identify the polluter? Yes, I can identify the polluter – polluter is MV ... . No, I cannot identify the polluter.', zh: '你能识别污染船吗？是的，我能识别污染船，污染船是...船。不，我不能识别污染船'),
    MaritimePhrase(id: '3.2.14.10', category: 'traffic', en: 'What is course and speed of the polluter? Course of the polluter ... degrees, speed ... knots. The polluter left the scene.', zh: '污染船的航向和航速是多少？污染船的航向是...度，航速是...节。污染船已离开现场'),
    MaritimePhrase(id: '3.2.15.1', category: 'traffic', en: 'I have / MV ... has damage above / below waterline. I have / MV ... has stability problems - heavy icing.', zh: '我（船）在水线以上/下有较大损坏。由于严重冰情，我（船）稳性有问题'),
    MaritimePhrase(id: '3.2.15.2', category: 'traffic', en: 'What kind of assistance is required? I require / MV ... requires tug assistance/ice-breaker assistance / escort / ...', zh: '你（船）需要何种援助？我（船）需要拖轮/破冰船援助/护航等'),
    MaritimePhrase(id: '3.2.16.1', category: 'traffic', en: 'The distance between MVXX and you is decreasing according to VTS recorder. You are dragging using my judgment. Check your anchoring position right away.', zh: '根据VTS记录，XX船与你船之间的距离正不断减少。根据我的判断，你船正在走锚。立即校核你的锚位'),
    MaritimePhrase(id: '3.2.16.2', category: 'traffic', en: 'I am / MV ... is dragging. I am / MV ... is standing by my main engine and anchor(s). I will heave up my anchor and shift my anchoring position to ... . Can I adjust my anchoring position by myself? Yes, you can adjust your anchoring position by yourself. No, you can not adjust your anchoring position by yourself. You will have permission to adjust your anchoring position when pilot on board. Advi', zh: '我（船）正在走锚。我（船）正在备车、备锚。我（船）将起锚移锚位至...处。我能自己调整锚位吗？是的，你可以自己调整锚位。不，你不可以自己调整锚位。只有当引水在船时，你才可以调整锚位。建议：你船位处潮流很急。谨慎驾驶'),
    MaritimePhrase(id: '3.2.16.3', category: 'traffic', en: 'I am / MV ... is not dragging. I am only dredging anchor. Warning: You are passing through a heavy traffic area. It is dangerous dredging anchor here. Instruction: Do not dredge anchor.', zh: '我船没有走锚。我船只是在拖锚。警告：你船正在通过交通密集区。在这里拖锚是很危险的。指令：不要拖锚！'),
    MaritimePhrase(id: '3.2.17.1', category: 'traffic', en: 'You are running into danger shallow water .... (cardinal points) of you. submerged wreck ... (cardinal points) of you.fog bank ... (cardinal points) of you. risk of collision (with vessel bearing ... degrees, distance ...kilometers/ nautical miles).bridge is defective. Your course is deviating from the radar reference line. You are proceeding at a dangerous speed.', zh: '你将有危险，你的....（罗经点）有浅滩。你的....（罗经点）有沉船;你的....（罗经点）有雾堤。（与方位....度，距离....公里/海里的船舶）有碰撞危险;桥有损坏。你的航向正偏离雷达基线。你正以危险速度行驶'),
    MaritimePhrase(id: '3.2.17.2', category: 'traffic', en: 'You must proceed by the fairway / route ... . keep to the ... (cardinal points) of the fairway line / radar reference line.', zh: '你必须在...航道/...航路航行。保持在主航道线/雷达基线的...（罗经点）侧'),
    MaritimePhrase(id: '3.2.17.3', category: 'traffic', en: 'Your track is parallel with the reference line.diverging from the reference line.', zh: '你船的航向与雷达基线平行。与雷达基线交叉'),
    MaritimePhrase(id: '3.2.17.4', category: 'traffic', en: 'What is your present course / heading? My present course / heading is ... degrees.', zh: '你船现在的航向/船首向？我船现在的航向/船首向是...度'),
    MaritimePhrase(id: '3.2.17.6', category: 'traffic', en: 'It is dangerous to anchor in your present position/to remain in your present position/ to alter course to the... degrees.', zh: '在你现在的位置抛锚是危险的/在你现在的位置停留是危险的/改驶航向至...度是危险的'),
    MaritimePhrase(id: '3.3', category: 'traffic', en: 'Performing / co-ordinating SAR – operations', zh: '执行、协调搜救行动P56'),
    MaritimePhrase(id: '3.3.1', category: 'traffic', en: 'I will act as On-scene Co-ordinator. Vessels are advised to proceed to position ... to start rescue.', zh: '我将担任现场指挥官。通知各船舶前往...开始救助'),
    MaritimePhrase(id: '3.3.2', category: 'traffic', en: 'Can you proceed to distress position? Yes, I can proceed to distress position. No, I cannot proceed to distress position.', zh: '你能驶往遇险地点吗？是的，我能驶往遇险地点。不，我不能驶往遇险地点'),
    MaritimePhrase(id: '3.3.3', category: 'traffic', en: 'What is your ETA at distress position? My ETA at distress position within ... hours / at ... UTC.', zh: '你何时能驶抵遇险地点？我将在...小时内/...UTC驶抵遇险地点'),
    MaritimePhrase(id: '3.3.4', category: 'traffic', en: 'MAYDAY position is not correct. Correct MAYDAY position is ... .', zh: '遇险信号的位置不正确。正确的遇险信号位置是...'),
    MaritimePhrase(id: '3.3.5', category: 'traffic', en: 'Carry out search pattern ... starting at ... UTC. Carry out radar search. Initial course ... degrees, search speed ... knots.', zh: '于...UTC开始执行...搜救方式。执行雷达搜救。初始航向...度，搜寻速度...节'),
    MaritimePhrase(id: '3.3.6', category: 'traffic', en: 'MV ... allocated track number ... . Search speed now ... knots. MV ... adjust interval between vessels to ...kilometers / nautical miles. Adjust track spacing to ...kilometers / nautical miles.', zh: '...轮被分配在...号搜寻航线。现在搜寻速度为...节。...轮调整船舶之间的间距为...公里/海里。调整搜寻航线的间隔为...公里/海里'),
    MaritimePhrase(id: '3.3.7', category: 'traffic', en: 'Alter course to ... degrees (- at ... UTC). for next leg of track now / at ... UTC.', zh: '（在...UTC）改向至...度。现在/在...UTC改向到下一段搜寻航线'),
    MaritimePhrase(id: '3.3.8', category: 'traffic', en: 'Continue search in position ... . We resume search in position ... .', zh: '在...位置处继续搜寻。我们在...位置处继续搜寻'),
    MaritimePhrase(id: '3.3.9', category: 'traffic', en: 'Crew has abandoned vessel / MV ... . Keep sharp lookout for lifeboats / life crafts / persons in water / ... .', zh: '船员已弃船/放弃...船。严密了望救生艇/筏/落水人员...'),
    MaritimePhrase(id: '3.3.10', category: 'traffic', en: 'What is the result of search? The result of search is negative. Sighted vessel in position ... .lifeboats / life rafts in position ... .persons in water / ... in position ... .', zh: '搜救结果如何？P58搜寻没有结果。发现目标船/救生艇/筏/落水人员位置在...'),
    MaritimePhrase(id: '3.3.11', category: 'traffic', en: 'Can you pick up survivors? Yes, I can pick up survivors. No, I cannot pick up survivors.', zh: '你能捞起幸存者吗？是的，我能捞起幸存者。不，我不能捞起幸存者'),
    MaritimePhrase(id: '3.3.12', category: 'traffic', en: 'MV ..., you are advised to proceed to position ... to pick up survivors. Yes, MV ... / I will proceed to pick up survivors. Stand by lifeboats / liferafts. Picked up... survivors in position ... /lifeboats / liferafts (with ... persons / casualties) in position ... / persons / casualties in lifejackets in position ... .', zh: '...轮，通知你前往...处去救幸存者。是，我将前往...处去救幸存者。备好艇、筏。在...位置处捞起...名幸存者/...个救生艇/筏，上有...人/...伤亡者/...名穿着救生衣的人员/伤亡者'),
    MaritimePhrase(id: '3.3.13', category: 'traffic', en: 'What’s the condition of survivors? Survivors in bad / good condition.', zh: '幸存者状况如何？幸存者状况不好/良好'),
    MaritimePhrase(id: '3.3.14', category: 'traffic', en: 'Do you require medical assistance? Yes, I require medical assistance. No, I do not require medical assistance.', zh: '你需要医疗援助吗？是的，我需要医疗援助。不，我不需要医疗援助'),
    MaritimePhrase(id: '3.3.15', category: 'traffic', en: 'Try to obtain information from survivors. There are still ... lifeboats / liferafts with survivors. no more lifeboats / liferafts. Total number of persons on board was ... .', zh: '设法从幸存者中获得信息。这里还有载有...名幸存者的救生艇/筏。再没有救生艇/筏了。在船上的总人数是...'),
    MaritimePhrase(id: '3.3.16', category: 'traffic', en: 'All persons / ... persons rescued. There is no hope to rescue more persons. We finish with SAR - operations. You / MV ... may stop search and proceed with voyage. Thank you for co-operation.', zh: '所有人员/...人被救起。没有希望营救更多的人员。我们已完成搜救行动。你（船）可以停止搜救，继续航行。谢谢你的合作'),
    MaritimePhrase(id: '4.1.1', category: 'pilotage', en: 'Shore based pilotage by VTS.', zh: '由VTS提供的岸基助航服务'),
    MaritimePhrase(id: '4.1.2', category: 'pilotage', en: 'Pilotage at ...(name) Pilot Station has been suspended until ... (date and local time).', zh: '...（名称）引航站的引航业务暂停，直到...（日期和地方时）'),
    MaritimePhrase(id: '4.1.3', category: 'pilotage', en: 'Pilotage at ...(name) Pilot Station has been resumed.', zh: '...（名称）引航站的引航业务恢复'),
    MaritimePhrase(id: '4.1.4', category: 'pilotage', en: 'The pilot cannot embark at ... (name) Pilot Station due to ...', zh: '由于...，引航员不能在...（名称）引航站上船'),
    MaritimePhrase(id: '4.1.5', category: 'pilotage', en: 'Do you accept shore-based navigational assistance from VTS Centre?', zh: '你是否接受VTS中心提供的岸基助航服务？'),
    MaritimePhrase(id: '4.1.6', category: 'pilotage', en: 'Yes, I accept shore-based navigational assistance.', zh: '是的，我接受岸基助航帮助'),
    MaritimePhrase(id: '4.1.7', category: 'pilotage', en: 'No, I do not accept shore-based navigational assistance', zh: '不，我不接受岸基助航帮助'),
    MaritimePhrase(id: '4.2.2', category: 'pilotage', en: 'Yes, VTS navigational assistance is available.', zh: '是的，VTS可以提供助航'),
    MaritimePhrase(id: '4.2.4', category: 'pilotage', en: 'Do you accept shore-based navigational assistance from VTS Center?', zh: '你是否接受VTS中心提供的岸基助航帮助?'),
    MaritimePhrase(id: '4.2.5', category: 'pilotage', en: 'Yes, I accept shore-based navigational assistance. No, I do not accept shore-based navigational assistance.', zh: '是的，我接受岸基助航帮助。不，我不接受岸基助航帮助'),
    MaritimePhrase(id: '4.2.7', category: 'pilotage', en: 'My position is bearing ... degrees ..., distance ... nautical miles from ...', zh: '我的船位在...方位...度，距离...海里'),
    MaritimePhrase(id: '4.2.8', category: 'pilotage', en: 'How was your position obtained?', zh: '你的船位是如何获得的？'),
    MaritimePhrase(id: '4.2.9', category: 'pilotage', en: 'My position was obtained by GPS / RADAR / cross-bearing / astronomical observation / ..', zh: '我的船位由GPS/雷达/交叉方位/天文观测/...测得'),
    MaritimePhrase(id: '4.2.10', category: 'pilotage', en: 'I have located you on my radar screen.', zh: '我已在雷达上发现你船'),
    MaritimePhrase(id: '4.2.11', category: 'pilotage', en: 'Your position is bearing ... degrees, distance ... nautical miles from ...', zh: '你的船位在...方位...度，距离...海里'),
    MaritimePhrase(id: '4.2.12', category: 'pilotage', en: 'I cannot locate you on my radar screen.', zh: '我无法在雷达上发现你船'),
