    MaritimePhrase(id: '5.2.1.13', category: 'mooring', en: 'Route…/Traffic Lane…has been suspended/discontinued.', zh: '...航路/通航分道已暂停通航/已停止通航'),
    MaritimePhrase(id: '5.2.1.14', category: 'mooring', en: 'Area around … temporarily closed for navigation.', zh: '在...周围区域临时封航'),
    MaritimePhrase(id: '5.2.2.2', category: 'mooring', en: 'Do not overtake/cross the fairway.', zh: '...航道/不得追越/横穿航道'),
    MaritimePhrase(id: '5.2.2.3', category: 'mooring', en: 'Vessels must avoid /keep clear of this area/area…', zh: '船舶必须避开/让清该区域/...区域'),
    MaritimePhrase(id: '5.2.2.4', category: 'mooring', en: 'Avoid this area, no-possibility for vessels to turn.', zh: '避开该区域，船舶不可能调头'),
