    MaritimePhrase(id: '5.3.11', category: 'mooring', en: 'You cannot proceed, must select position to drop anchor right now.', zh: '你不能继续航行，必须立即择地抛锚'),
    MaritimePhrase(id: '5.3.12', category: 'mooring', en: 'Navigation is dangerous now, you must drop anchor, anchor position Latitude…Longitude…has been allocated.', zh: '现在航行很危险，你必须抛锚，给你指定的锚位是纬度...、经度...'),
    MaritimePhrase(id: '5.3.13', category: 'mooring', en: 'Visibility is increasing, traffic clearance again，vessels inbound / outbound one by one in command of patrol boat on scene.', zh: '能见度转好，恢复通航，各轮请按序进出港，听从现场巡逻艇的指挥'),
    MaritimePhrase(id: '6.1.1', category: 'emergency', en: 'MV…,are you keep watch on VHF Channel …? Sorry, I’m forget switching to VHF Channel…after use another Channel. Sorry, I put VHF signal strength too low. 6.1.2 In this area, you must stand by on VHF channel…at all times.', zh: '…轮，你有没有收听VHF…频道？对不起，我使用另一频道后忘了转到…频道。对不起，我的高频音量开得太小了。6.1.2在这个水域必须始终收听VHF...频道'),
    MaritimePhrase(id: '6.1.3', category: 'emergency', en: 'You are not complying with traffic regulations.', zh: '你船没有遵守通航规则'),
    MaritimePhrase(id: '6.1.4', category: 'emergency', en: 'MV… , you are not complying the traffic separation scheme. You must keep on the starboard side of the fairway.', zh: '…轮，你没有遵守分道通航制，你必须保持在航道的右侧'),
    MaritimePhrase(id: '6.1.5', category: 'emergency', en: 'You are not keeping to the correct traffic lane.', zh: '你船没有保持在正确的通航分道上'),
    MaritimePhrase(id: '6.1.6', category: 'emergency', en: 'Fairway speed is... knots.', zh: '航道内限定的速度...节'),
    MaritimePhrase(id: '6.1.7', category: 'emergency', en: 'Your ship sailed into the prohibited area.', zh: '你船进入了禁航区'),
    MaritimePhrase(id: '6.1.8', category: 'emergency', en: 'Your ship entered the territorial waters without our permission.', zh: '你船未经许可进入了领水'),
    MaritimePhrase(id: '6.1.9', category: 'emergency', en: 'Even in emergency, you should report to us and apply for permission.', zh: '即使在紧急情况下，你船也应该向我们报告并申请允许进入我领水'),
    MaritimePhrase(id: '6.1.10', category: 'emergency', en: 'You have anchored in a wrong position, you must heave up anchor and shift to the …anchorage as soon as possible.', zh: '你船抛错了锚位，必须尽快起锚，然后去...锚地抛锚'),
    MaritimePhrase(id: '6.1.11', category: 'emergency', en: 'You have anchored in the fairway, you must heave up anchor and shift to the anchorage area.', zh: '你船抛在航道上，必须起锚并移到锚地里面'),
    MaritimePhrase(id: '6.1.12', category: 'emergency', en: 'Navigation trials/ speed testing/ launching life boat for drills is prohibited in VTS Area without approval.', zh: '未经批准禁止在港进行试航/测速/吊放救生艇演习...'),
    MaritimePhrase(id: '6.1.13', category: 'emergency', en: 'You should report your ETA to … VTS … hour(s) in advance on your arrival at …port..', zh: '你应在到港前...小时向...VTS报告ETA'),
    MaritimePhrase(id: '6.1.14', category: 'emergency', en: 'You should report your movement to …VTS when passing through …report line inbound / outbound.', zh: '你应在经过...报告线时向…VTS报告你船动态'),
    MaritimePhrase(id: '6.1.15', category: 'emergency', en: 'You should report to …VTS right after anchoring /berthing.', zh: '你应在抛锚/靠泊后立即向VTS报告'),
    MaritimePhrase(id: '6.1.16', category: 'emergency', en: 'You should report your movement to …VTS …minutes ahead of heaving up anchor /departure.', zh: '你应在起锚/离泊前...分钟向VTS报告动态'),
    MaritimePhrase(id: '6.1.17', category: 'emergency', en: 'You should report name of big vessel and barge, name of barge cargo; start time and end time of transferring cargo to …VTS.', zh: '你应向…VTS报告水上过驳受载船及卸驳船船名、过驳货物名称、开始或结束过驳时间'),
    MaritimePhrase(id: '6.1.18', category: 'emergency', en: 'According to my radar, your course does not comply with Rule 10 of the COLREGs.', zh: '我的雷达显示，你船航向没有遵守《国际海上避碰规则》第10条的规定'),
    MaritimePhrase(id: '6.1.20', category: 'emergency', en: 'Do you know your action have violated our port regulation?', zh: '你知道你的行为已违反了我们的港章吗？'),
    MaritimePhrase(id: '6.1.21', category: 'emergency', en: 'Were you informed of our port regulations before entering port?', zh: '你在进港前有没有被告之我们的港口规定？'),
    MaritimePhrase(id: '6.1.22', category: 'emergency', en: 'Why did you run into the prohibited area?', zh: '你为什么闯入禁航区呢？'),
    MaritimePhrase(id: '6.1.23', category: 'emergency', en: 'Because it was dark and foggy when I passing the channel, it was difficulocal time to get a fix on my ship', zh: '因为当我船驶过该水域时天黑又有雾，难以定船位'),
    MaritimePhrase(id: '6.1.24', category: 'emergency', en: 'You can use radar or GPS.', zh: '你可以使用雷达或GPS'),
    MaritimePhrase(id: '6.1.27', category: 'emergency', en: 'You knowingly violated the Port Regulation. You must be responsible for it.', zh: '你是明知故犯，你必须对此负责'),
    MaritimePhrase(id: '6.1.29', category: 'emergency', en: 'You must write a statement to the Harbour Master about the matter of violations.', zh: '你必须就违章一事向我们的港长写一份情况报告'),
    MaritimePhrase(id: '6.1.30', category: 'emergency', en: 'I tell you that you will be fined for such a violations according to our rules.', zh: '我告诉你根据我们的规则，你船会因为这一违章而被罚款'),
    MaritimePhrase(id: '6.1.31', category: 'emergency', en: 'You see, I violated this regulation just because of carelessness. So I hope you will forgive me.', zh: '你知道，我只是因为粗心而违章的，所以我希望你会原谅我'),
    MaritimePhrase(id: '6.1.32', category: 'emergency', en: 'Whether you are fined or not will be decided by the Harbour Master.', zh: '你们是否会被处罚将有监督长决定'),
    MaritimePhrase(id: '6.1.33', category: 'emergency', en: 'As a rule, you should report this mater to us as soon as you discover it, or at least when you arrive here.', zh: '通常来说，你们一发现这种情况或者至少当你船到达这里时就应立即向我们报告'),
    MaritimePhrase(id: '6.1.34', category: 'emergency', en: 'Obeying the Port Regulations is very important. You should observe them at all times.', zh: '遵守港章是非常重要的，你必须始终遵守'),
    MaritimePhrase(id: '6.1.35', category: 'emergency', en: 'You must be careful not to violate this regulation again. Sure, we won’t.', zh: '你必须记住不要再违章了。放心，我们不会再违章了'),
    MaritimePhrase(id: '7.1.1.1', category: 'general', en: 'Vessel in position ... on fire / had explosion /aground / flooded / in collision / (with .. ) listing / in danger of capsizing / sinking/ disabled and adrift / abandoned / ...', zh: '位于...的船舶发生火灾/发生爆炸/搁浅/进水/（与...）碰撞/正在横倾/有倾覆的危险/正在下沉/操纵失灵并在漂移/弃船/...'),
    MaritimePhrase(id: '7.1.1.2', category: 'general', en: 'What is your position? My position ... .', zh: '你的位置在哪里？我的位置在...'),
    MaritimePhrase(id: '7.1.1.3', category: 'general', en: 'Did you transmit a DSC distress alert? Yes. I transmitted a DSC alert Yes. I transmitted a DSC alert by mistake', zh: '你发过DSC遇险报警吗?是的，我发过DSC报警是的，我误发过DSC报警'),
    MaritimePhrase(id: '7.1.1.5', category: 'general', en: 'My present course ... degrees, my speed ... knots.', zh: '我的航向是...度，航速是...节'),
    MaritimePhrase(id: '7.1.1.10', category: 'general', en: 'What kind of assistance is required?', zh: '需要什么样的救助?'),
    MaritimePhrase(id: '7.1.1.11', category: 'general', en: 'I / MV…requires fire fighting assistance/ breathing apparatus/ fire pumps/ medical assistance/…', zh: '我/...轮需要消防援助/氧气面罩/消防泵/医疗援助/...'),
    MaritimePhrase(id: '7.1.1.12', category: 'general', en: 'I / MV…requires escort/ tug assistance/ navigational assistance/…', zh: '我/...轮需要护航/拖轮协助/导航援助/...'),
    MaritimePhrase(id: '7.1.1.13', category: 'general', en: 'Will you abandon vessel? I will not abandon vessel. I will abandon vessel at ...local time', zh: '你是否将弃船？我不弃船。我将在地方时...时弃船'),
    MaritimePhrase(id: '7.1.1.14', category: 'general', en: 'Close all of oil valves and report.', zh: '关闭所有的油路阀门并报告'),
    MaritimePhrase(id: '7.1.1.15', category: 'general', en: 'All of oil valves are closed.', zh: '所有的油路阀门已关闭'),
    MaritimePhrase(id: '7.1.1.16', category: 'general', en: 'How many lifeboats / liferafts (with how many persons) will you launch?', zh: '你将放下多少救生艇/筏（能载多少人员）'),
