    MaritimePhrase(id: '7.2.1.6', category: 'general', en: 'No, I / MV ... cannot stop spillage.', zh: '不，我轮不能制止溢油'),
    MaritimePhrase(id: '7.2.1.8', category: 'general', en: 'I require / MV ... requires oil clearance assistance. floating booms / oil dispersants / ... .', zh: '我/...轮需要清除油污援助。围油栏/消油剂/...'),
    MaritimePhrase(id: '7.2.1.9', category: 'general', en: 'Stay in vicinity of pollution and co-operate with oil clearance team.', zh: '停留在污染区附近，并与油污清除队合作'),
